cd /tmp/claude-0/-home-user-EdFringeNow/d828fc38-5d63-54d0-8e4f-003d05f8e65c/scratchpad && python3 -c "
import re, json
html = open('page.html').read()
m = re.search(r'<script id=\"__NEXT_DATA__\" type=\"application/json\">(.*?)</script>', html, re.S)
d = json.loads(m.group(1))
open('next.json','w').write(json.dumps(d, indent=1))
def walk(o, path=''):
    if isinstance(o, dict):
        if 'performances' in o and isinstance(o['performances'], list) and o['performances']:
            print('PERFORMANCES at', path, 'n=', len(o['performances']))
            print(json.dumps(o['performances'][0], indent=1)[:1500])
            return True
        for k,v in o.items():
            if walk(v, path+'/'+k): return True
    elif isinstance(o, list):
        for i,v in enumerate(o[:5]):
            if walk(v, path+f'[{i}]'): return True
    return False
walk(d)
"

